// Merge depth content into DAILY_CONTENT (day N = index N-1)
(function() {
  if (typeof DAILY_CONTENT === 'undefined') return;
  Object.keys(DAILY_DEPTH).forEach(function(key) {
    const day = parseInt(key, 10);
    const entry = DAILY_DEPTH[key];
    const target = DAILY_CONTENT[day - 1];
    if (!target) return;
    const study = entry.study || (entry.sameStudyAs && DAILY_DEPTH[entry.sameStudyAs] && DAILY_DEPTH[entry.sameStudyAs].study);
    if (study) target.study = study;
    if (entry.deep) target.deep = entry.deep;
  });
})();
